import copy
VISUALS={}
def put(key,kind,titles,footers,**data):
 assert len(titles)==len(footers)==4,key
 VISUALS[key]=[dict(kind=kind,title=titles[i],footer=footers[i],focus=i,**copy.deepcopy(data)) for i in range(4)]
def table(key,headers,rows,footers,titles=None):put(key,'table',titles or ['记录条件','逐项比较','继续推导','核对结论'],footers,headers=headers,rows=rows)
def flow(key,nodes,footers,titles=None):put(key,'flow',titles or ['看起点','看路径','看结果','连成过程'],footers,nodes=nodes)
def bits(key,rows,footers,titles=None):put(key,'bits',titles or ['固定宽度','跟踪位模式','按规则解释','核对范围'],footers,rows=rows)
def cpu(key,footers,titles=None,**data):put(key,'cpu',titles or ['准备状态','选择路径','完成操作','保存结果'],footers,**data)

